--
-- Estructura para la vista `v_academic_courses_with_areas`
--
DROP TABLE IF EXISTS `v_academic_courses_with_areas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u577899998_aldair1908`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_academic_courses_with_areas`  AS SELECT `ac`.`id` AS `id`, `ac`.`school_id` AS `school_id`, `ac`.`area_id` AS `area_id`, `a`.`name` AS `area_name`, `a`.`color` AS `area_color`, `ac`.`name` AS `course_name`, `ac`.`description` AS `description`, `ac`.`level` AS `level`, `ac`.`created_at` AS `created_at` FROM (`academic_courses` `ac` left join `areas` `a` on(`ac`.`area_id` = `a`.`id`)) WHERE `ac`.`school_id` = 1 ;

